#!/usr/bin/env bash
# The animals' SVGs are generated by tools/art/build.mjs, committed, and must match the scripts.
set -uo pipefail
root="$(cd "$(dirname "$0")/../.." && pwd)"
art="$root/src/animals/art"
fail=0
check() { if eval "$2"; then echo "ok   $1"; else echo "FAIL $1: $2" >&2; fail=1; fi; }

node "$root/tools/art/build.mjs" > /dev/null
# Rebuilding changes nothing on disk (compared with git's index, so staged output counts too).
check test_build_is_reproducible 'git -C "$root" diff --quiet -- src/animals/art && [ -z "$(git -C "$root" ls-files --others --exclude-standard -- src/animals/art)" ]'

ids=(yaguarete lobo_marino pinguino condor hornero yacare flamenco guanaco ballena)
missing=""
for id in "${ids[@]}"; do [ -f "$art/$id-simple.svg" ] || missing+=" $id"; done
check test_every_animal_has_simple '[ -z "$missing" ]'
missing_full=""
for id in "${ids[@]}"; do [ -f "$art/$id-full.svg" ] || missing_full+=" $id"; done
check test_every_animal_has_full '[ -z "$missing_full" ]'

# Each SVG uses only the paper, "none" and its own ink, which must be the ink in animals.gd.
inks=($(sed -n '/^const _INKS/,/^]/p' "$root/src/animals/animals.gd" | grep -oE '#[0-9a-fA-F]{6}' | tr 'A-F' 'a-f'))
bad=""
for i in "${!ids[@]}"; do
  for f in "$art/${ids[$i]}"-*.svg; do
    colors="$(grep -oE '(fill|stroke)="[^"]+"' "$f" | sed -E 's/.*="([^"]+)"/\1/' | sort -u | tr '\n' ' ')"
    for c in $colors; do
      case "$c" in "#f1e6d6"|none|"${inks[$i]}") ;; *) bad+=" $(basename "$f"):$c" ;; esac
    done
    grep -q "${inks[$i]}" "$f" || bad+=" $(basename "$f"):no-ink"
  done
done
check test_inks_match_animals_gd '[ "${#inks[@]}" = 9 ] && [ -z "$bad" ]'

# The brand art (app icon, Android adaptive icon layers, feature graphic), by tools/art/brand.mjs.
brand="$root/src/brand"
node "$root/tools/art/brand.mjs" > /dev/null
check test_brand_is_reproducible 'git -C "$root" diff --quiet -- src/brand && [ -z "$(git -C "$root" ls-files --others --exclude-standard -- src/brand)" ]'
missing_brand=""
for f in icon icon-foreground icon-background feature; do [ -f "$brand/$f.svg" ] || missing_brand+=" $f"; done
check test_brand_files_exist '[ -z "$missing_brand" ]'
# Only the paper, the board's line and given shade, and the animals' inks.
allowed=" #f1e6d6 #4a3b2e #e3d2ba none ${inks[*]} "
bad_brand=""
for f in "$brand"/*.svg; do
  for c in $(grep -oE '(fill|stroke)="[^"]+"' "$f" | sed -E 's/.*="([^"]+)"/\1/' | sort -u); do
    case "$allowed" in *" $c "*) ;; *) bad_brand+=" $(basename "$f"):$c" ;; esac
  done
done
check test_brand_uses_the_palette '[ -z "$bad_brand" ]'
# The icon and the feature graphic are opaque (Play rejects transparency): a paper rect fills them.
opaque=""
for f in icon icon-background feature; do
  grep -q '<rect x="0" y="0" width="100%" height="100%" fill="#f1e6d6"/>' "$brand/$f.svg" 2>/dev/null || opaque+=" $f"
done
check test_brand_backgrounds_are_opaque '[ -z "$opaque" ]'
exit "$fail"
